function [mch,mfc,mfq,mvopt,mcopt,mxc,xc_out] = sim_modelcountdiscrete_noisyleaky(betav,betac,betar,ncrit,omega,delta_c,delta_u,sigma,cfg)
% Simulate choices from the discrete count-based noisy/leaky model.
%
% ncrit is a genuinely discrete parameter and must be an integer.
%
% During the initial count-based phase, the model repeats the previously
% selected option with probability omega while fewer than ncrit outcomes
% have been observed from that option. Once ncrit outcomes have been
% collected, or once the model switches away from that option, choices are
% generated by the ordinary logistic policy.
%
% Inputs:
%   betav   : sensitivity to target-aligned value
%   betac   : sensitivity to uncertainty/certainty
%   betar   : repetition bias
%   ncrit   : integer sample-count criterion
%   omega   : repetition probability during the count-based phase
%   delta_c : leak rate for the chosen option
%   delta_u : leak rate for the unchosen option
%   sigma   : learning noise
%   cfg     : simulation configuration
%
% Outputs:
%   mch     : simulated sampling choices
%   mfc     : simulated final choices
%   mfq     : final state-aligned evidence for option 1
%   mvopt   : target-directed sampling choices
%   mcopt   : uncertainty-directed sampling choices
%   mxc     : state-aligned evidence for option 1 during sampling
%   xc_out  : complete latent belief trajectories

%% Check configuration

if ~isfield(cfg,'leakrule') || isempty(cfg.leakrule), cfg.leakrule = 'post'; end
if ~isfield(cfg,'shuffle') || isempty(cfg.shuffle), cfg.shuffle = false; end
if ~isfield(cfg,'same1st') || isempty(cfg.same1st), cfg.same1st = false; end
if ~isfield(cfg,'fix1st') || isempty(cfg.fix1st), cfg.fix1st = false; end
if ~isfield(cfg,'ncrit_min') || isempty(cfg.ncrit_min), cfg.ncrit_min = 1; end
if ~isfield(cfg,'ncrit_max') || isempty(cfg.ncrit_max), cfg.ncrit_max = 20; end

if cfg.same1st, cfg.fix1st = false; end
if cfg.fix1st, cfg.same1st = false; end

if ~isscalar(ncrit) || ~isfinite(ncrit) || ncrit ~= round(ncrit)
    error('ncrit must be a finite integer scalar.');
end

if ncrit < cfg.ncrit_min || ncrit > cfg.ncrit_max
    error('ncrit must lie between %d and %d.',cfg.ncrit_min,cfg.ncrit_max);
end

if ~isscalar(omega) || ~isfinite(omega) || omega < 0 || omega > 1
    error('omega must be a finite scalar between 0 and 1.');
end

if ~isfield(cfg,'choices') || isempty(cfg.choices), error('cfg.choices is required.'); end
if ~isfield(cfg,'colorop') || isempty(cfg.colorop), error('cfg.colorop is required.'); end
if ~isfield(cfg,'targetc') || isempty(cfg.targetc), error('cfg.targetc is required.'); end
if ~isfield(cfg,'cfac') || isempty(cfg.cfac), error('cfg.cfac is required.'); end

%% Initialize outputs

nseq = numel(cfg.choices);
cfac = cfg.cfac;

mch = cell(nseq,1);
mfc = nan(nseq,1);
mfq = nan(nseq,1);
mxc = cell(nseq,1);
mvopt = cell(nseq,1);
mcopt = cell(nseq,1);
xc_out = cell(nseq,1);

%% Simulate sequences

for iseq = 1:nseq

    nsmp = numel(cfg.choices{iseq});

    mch{iseq} = nan(1,nsmp);
    mvopt{iseq} = nan(1,nsmp);
    mcopt{iseq} = nan(1,nsmp);

    xc = nan(nsmp+1,2);
    xc(1,:) = 0;

    % Indicates whether each option remains eligible for the initial
    % count-based repetition mechanism.
    bc = true(1,2);

    % Number of observed outcomes sampled from each option.
    nselected = zeros(1,2);

    %% Select first option

    if cfg.same1st
        mch{iseq}(1) = cfg.choices{iseq}(1);
    elseif cfg.fix1st
        mch{iseq}(1) = cfg.fix1st;
    else
        mch{iseq}(1) = randi(2);
    end

    %% Prepare outcome sequence

    colorv = cfg.colorop{iseq};

    if cfg.shuffle
        colorv = colorv(:,randperm(nsmp));
    end

    %% Simulate sampling choices

    for ismp = 2:nsmp

        ch = mch{iseq}(ismp-1);
        un = 3-ch;

        % The previous choice generated one additional observation.
        nselected(ch) = nselected(ch)+1;

        %% Update beliefs

        switch lower(cfg.leakrule)

            case 'pre'

                xc(ismp,ch) = (1-delta_c)*xc(ismp-1,ch)+colorv(ch,ismp-1)*cfac+randn*sigma;
                xc(ismp,un) = (1-delta_u)*xc(ismp-1,un);

            otherwise

                xc(ismp,ch) = xc(ismp-1,ch)+colorv(ch,ismp-1)*cfac+randn*sigma;
                xc(ismp,un) = xc(ismp-1,un);

                xc(ismp,ch) = (1-delta_c)*xc(ismp,ch);
                xc(ismp,un) = (1-delta_u)*xc(ismp,un);
        end

        %% Compute ordinary logistic policy

        dv = betav*(xc(ismp,1)-xc(ismp,2))*cfg.targetc(iseq);
        dv = dv-betac*(abs(xc(ismp,1))-abs(xc(ismp,2)));
        dv = dv+betar*(3-2*ch);

        %% Apply count-based policy

        % Because nselected is incremented before this comparison, ncrit = 5
        % means that the count policy is used after observations 1--4. The
        % ordinary logistic policy begins after observation 5 is obtained.
        in_count_phase = bc(ch) && nselected(ch) < ncrit;

        if in_count_phase
            pc = nan(1,2);
            pc(ch) = omega;
            pc(un) = 1-omega;
        else
            pc = nan(1,2);

            if betac > 100
                pc(1) = double(dv > 0);

                if dv == 0, pc(1) = 0.5; end
            else
                pc(1) = 1/(1+exp(-dv));
            end

            pc(2) = 1-pc(1);
        end

        %% Simulate next choice

        mch{iseq}(ismp) = 1+(rand > pc(1));

        %% Store target- and uncertainty-directed choices

        if cfg.targetc(iseq) ~= 0
            target_value = xc(ismp,:)*cfg.targetc(iseq);
            [~,target_option] = max(target_value);
            mvopt{iseq}(ismp) = mch{iseq}(ismp) == target_option;
        end

        [~,uncertain_option] = min(abs(xc(ismp,:)));
        mcopt{iseq}(ismp) = mch{iseq}(ismp) == uncertain_option;

        %% End count-based eligibility after the first switch

        ch_cur = mch{iseq}(ismp);

        if ch_cur ~= ch
            bc(ch) = false;
        end
    end

    %% Update beliefs after the final sampling choice

    ismp = nsmp+1;
    ch = mch{iseq}(nsmp);
    un = 3-ch;

    switch lower(cfg.leakrule)

        case 'pre'

            xc(ismp,ch) = (1-delta_c)*xc(ismp-1,ch)+colorv(ch,nsmp)*cfac+randn*sigma;
            xc(ismp,un) = (1-delta_u)*xc(ismp-1,un);

        otherwise

            xc(ismp,ch) = xc(ismp-1,ch)+colorv(ch,nsmp)*cfac+randn*sigma;
            xc(ismp,un) = xc(ismp-1,un);

            xc(ismp,ch) = (1-delta_c)*xc(ismp,ch);
            xc(ismp,un) = (1-delta_u)*xc(ismp,un);
    end

    %% Determine latent states

    if ~isfield(cfg,'latent') || isempty(cfg.latent)
        latent = sign(sum(colorv,2))';
        latent(latent == 0) = 1;
    else
        latent = cfg.latent(iseq,:);
    end

    %% Simulate final choice

    final_dv = xc(end,1)-xc(end,2);
    pfinal1 = 1/(1+exp(-final_dv));
    mfc(iseq) = 1+(rand > pfinal1);

    %% Store state-aligned evidence

    xe_final = latent.*xc(end,:);
    mfq(iseq) = xe_final(1);

    xe_sampling = bsxfun(@times,xc(2:end,:),latent);
    mxc{iseq} = xe_sampling(:,1)';

    xc_out{iseq} = xc;
end

end